<?php
namespace EventFlow\Application\Provider;
use DateTimeImmutable;use EventFlow\Application\Persistence\EventScope;
final readonly class NormalizedProviderWebhook{public const DEDUPE_VERSION='provider-dedupe-v1';public function __construct(public EventScope $eventScope,public string $provider,public ?string $nativeEventKey,public ?string $providerMessageId,public ?string $providerRequestId,public string $providerEventType,public string $normalizedType,public ?string $providerStatus,public ?string $reasonCode,public ?string $reasonMessage,public ?DateTimeImmutable $occurredAt,public string $payloadHash){if(!preg_match('/^[a-z][a-z0-9_.-]{1,63}$/',$provider)||!preg_match('/^[a-z][a-z0-9_.-]{1,63}$/',$normalizedType)||!preg_match('/^[a-f0-9]{64}$/',$payloadHash))throw new ProviderException('provider_webhook_invalid');}public function dedupeKey():string{return hash('sha256',self::DEDUPE_VERSION.'|'.$this->provider.'|'.($this->nativeEventKey??$this->payloadHash));}public function jobPayload():array{return ['event_id'=>$this->eventScope->eventId,'provider'=>$this->provider,'native_event_key'=>$this->nativeEventKey,'provider_message_id'=>$this->providerMessageId,'provider_request_id'=>$this->providerRequestId,'provider_event_type'=>$this->providerEventType,'normalized_type'=>$this->normalizedType,'provider_status'=>$this->providerStatus,'reason_code'=>$this->reasonCode,'reason_message'=>$this->reasonMessage,'occurred_at'=>$this->occurredAt?->format(DATE_ATOM),'payload_hash'=>$this->payloadHash,'dedupe_version'=>self::DEDUPE_VERSION];}}
